@Bean
@StepScope
FlatFileItemWriter<ContratoDepurado> depuraWriter(P305Properties p,
        @Value("#{jobExecutionContext['csi']}") int csi,
        @Value("#{jobExecutionContext['fechaProceso']}") LocalDate fecha) {
    return new FlatFileItemWriterBuilder<ContratoDepurado>()
            .name("depura")
            .resource(new FileSystemResource(p.archivoDepura()
                    .replace("{csi}", "%02d".formatted(csi))
                    .replace("{aammdd}", fecha.format(DateTimeFormatter.ofPattern("yyMMdd")))))
            .headerCallback(w -> w.write(DepuraLayout.header("0000S500", "0000S016")))   // tipo 01
            .lineAggregator(DepuraLayout::detalle)                                          // tipo 2
            .footerCallback(w -> w.write(DepuraLayout.trailer(contador.total())))            // tipo 99
            .build();
}

@Configuration
public class DepuracionJobConfig {

    /** 00000000-PRINCIPAL: LIBRERIAS, OPEN, PROCESOS, CIERRO. */
    @Bean
    Job depuracionContratos(JobRepository repo, Step fechasYPrecondicion,
                            Step cargaCifras, Step depuraContratos,
                            Step depuracionesComplementarias, Step enviaDepura,
                            JobExecutionDecider modo) {
        return new JobBuilder("S500P305", repo)
                .start(fechasYPrecondicion)          // 20000200 .. 20000400
                .next(cargaCifras)                   // 51000000-CAR-CIF
                .next(depuraContratos)               // 53000000-BORROC
                .next(modo).on("NORMAL").to(depuracionesComplementarias)   // B04P, prealtas, B07/B08, B48, B49
                .next(enviaDepura)
                .from(modo).on("MASIVO").to(enviaDepura)                   // TASKVALUE = 5
                .end().build();
    }

    /** TASKVALUE 5 = borrado masivo de clones; 0 = depuración normal. */
    @Bean
    JobExecutionDecider modo() {
        return (job, step) -> new FlowExecutionStatus(
                job.getJobParameters().getLong("modo", 0L) == 5 ? "MASIVO" : "NORMAL");
    }
}

@Component
@RequiredArgsConstructor
public class PrecondicionP127Tasklet implements Tasklet {

    private final ControlPasoRepository b00;     // S500B00CTRLPASO
    private final ControlCaptacionRepository b02;

    @Override
    @Transactional
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        var ctl = b02.find().orElseThrow(() -> new ProcesoAbortadoException("ERROR REG. DE CONTROL VACIO"));
        boolean mensual = ctl.fechaLote().getMonthValue() != ctl.fechaLinea().getMonthValue();
        boolean prueba = perfiles.esPrueba();
        if (prueba && !mensual) return RepeatStatus.FINISHED;   // en pruebas solo se valida al cierre

        var paso = b00.findForUpdate()
                .orElseThrow(() -> new ProcesoAbortadoException("ERROR B00CTRLPASO VACIO"));
        if (!(paso.paso01() == 127 && paso.paso02() == 127 && paso.paso03() == 127)) {
            throw new ProcesoAbortadoException("ERROR BASE NO ES SALIDA DEL P127");   // DMTERMINATE
        }
        paso.limpia();      // MOVE 0: una segunda corrida ya no pasa esta validación
        return RepeatStatus.FINISHED;  // END-TRANSACTION SYNC al confirmar la transacción
    }
}

@Component
@StepScope
@RequiredArgsConstructor
public class CriterioDepuracion implements ItemProcessor<Contrato, Contrato> {

    private final PagosPendientesRepository b25;          // S500B25PGOSPENDPE
    @Value("#{jobExecutionContext['fechaMesAnterior']}") private LocalDate hace30Dias;
    @Value("#{jobParameters['modo'] ?: 0}")              private long modo;

    @Override
    public Contrato process(Contrato b03) {
        boolean masivo = modo == 5;
        boolean migradoAntiguo = !masivo && b03.migradoS111() == 1
                && b03.fechaMigra().isBefore(hace30Dias);      // W77-MIGRADO-SINSDO
        boolean candidato = b03.status() == 3 || b03.status() == 4 || migradoAntiguo;
        if (!candidato) return null;

        if (masivo) {
            return b03.marcaClon() == 2 ? b03 : null;          // solo clones
        }
        if (b03.marcaClon() == 2) return null;                 // los clones no se tocan en modo normal
        if (b25.existsByContrato(b03.numContrato())) return null;   // 53000500-VALIDA-B25
        return b03;
    }
}

/** 53100000-BORRO-MOV: qué saldos deben estar en cero según producto e instrumento. */
public enum TipoDepuracion { AHORRO, RESTO, NINGUNA }

public static TipoDepuracion clasifica(Contrato b03) {
    int prd = b03.numProducto(), ins = b03.numInstrum();
    boolean sinActualNiBloqueo = b03.sdoActual().signum() == 0 && b03.sdoProtBloq().signum() == 0;

    if (prd == 500 && ins == 6) {
        return TipoDepuracion.AHORRO;                     // inversión de ahorro: no se revisa saldo
    }
    if (prd == 66 && ins == 90) {
        return sinActualNiBloqueo ? TipoDepuracion.RESTO : TipoDepuracion.NINGUNA;
    }
    return (sinActualNiBloqueo && b03.sdoFinCorte().signum() == 0)
            ? TipoDepuracion.RESTO : TipoDepuracion.NINGUNA;
}

/** WS-TABLA de 30 posiciones cargada de B09CIFRAS por producto, instrumento y moneda. */
@Component
@JobScope
public class CifrasDepuracion {

    private final Map<ClaveCifra, CifraB09> porClave = new LinkedHashMap<>();

    void carga(CifraB09 c) {                                   // 51100000-LLENO-TABLA
        if (porClave.size() == 30) {
            throw new ProcesoAbortadoException("B09 CON MAS DE 30 PRODUCTOS");
        }
        porClave.put(new ClaveCifra(c.producto(), c.instrumento(), c.moneda()), c);
    }

    /** 53210000-ACUM-DEPU + 53240000-SUMO. */
    void suma(Contrato b03) {
        var clave = new ClaveCifra(b03.numProducto(), b03.numInstrum(), b03.moneda());
        var cifra = porClave.get(clave);
        if (cifra == null) {
            throw new ProcesoAbortadoException("PROD B03 NO EN TABLA DE B09 PRODUCTO INEXISTENTE ID="
                    + clave);                                  // CALL SYSTEM DMTERMINATE
        }
        cifra.incrementaDepuradas();                           // ADD 1 TO WS-ELI
    }
}

@Service
@RequiredArgsConstructor
public class BorradoContratoService {

    private final ContratoRepository b03;
    private final MovimientoRepository b04;
    private final HistoricoRepository b06;
    private final CifrasDepuracion cifras;
    private final DepuraWriter depura;

    /**
     * 53200000-CHECO-INVAHO. En el fuente cada DELETE es una transacción DMSII propia;
     * aquí se agrupa el contrato y sus dependientes en una sola para que el borrado sea atómico.
     */
    @Transactional
    public void borraAhorro(Contrato c) {
        cifras.suma(c);
        b04.deleteByContrato(c.numContrato());     // 53250000-MOV + 53251000-NEXT: todos los B04
        b06.deleteByContrato(c.numContrato());     // 53260000-HIS
        b03.delete(c);                             // WS-BAN-B03
        depura.escribe(c);                         // 20000500-MOVE-WRITE-DEPURA
    }
}

/** 53410000-DELETE: una bandera por dataset. En Java cada repositorio borra lo suyo. */
private void borra(Set<Estructura> marcadas, Contrato c) {
    for (Estructura e : marcadas) {
        try {
            switch (e) {
                case B03 -> b03.delete(c);
                case B04 -> b04.deleteActual(c);
                case B06 -> b06.deleteActual(c);
                case B12 -> b12.deleteByContrato(c.numContrato());
                case B20 -> b20.deleteByContrato(c.numContrato());
                case B25 -> b25.deleteByContrato(c.numContrato());
                case B26 -> b26.deleteByContrato(c.numContrato());
                case B39 -> b39.deleteByContrato(c.numContrato());
                case B48 -> b48.deleteByContrato(c.numContrato());
                case B49 -> b49.deleteByContrato(c.numContrato());
                case B50 -> b50.deleteByContrato(c.numContrato());
                case B00, B09 -> { /* STORE, no DELETE: se graban al cierre */ }
            }
        } catch (DataAccessException ex) {
            throw new ProcesoAbortadoException("ERROR AL BORRAR " + e, ex);   // DMTERMINATE
        }
    }
}

@Component
@RequiredArgsConstructor
public class DepuracionB04P implements Tasklet {

    private final MovimientoPteRepository b04p;     // S500BD04TARJETAS / B04P
    @Value("#{jobExecutionContext['fechaAnioAnterior']}") private LocalDate haceUnAnio;

    /** 70000700-BORRO-B04PTEF: solo en modo normal. */
    @Override
    @Transactional
    public RepeatStatus execute(StepContribution c, ChunkContext ctx) {
        int borrados = b04p.deleteByFechaActualizacionBefore(haceUnAnio);
        c.incrementWriteCount(borrados);
        return RepeatStatus.FINISHED;
    }
}

